def extract_date(lines: list[str]) -> str | None:
    def collect(pats):
        counts: dict[str, int] = {}
        first_idx: dict[str, int] = {}
        for i, ln in enumerate(lines):
            up = ln.upper()
            up2 = re.sub(r'\b(\d{1,2}:\d{2}(:\d{2})?)\b', ' ', up)
            for pat in pats:
                m = pat.search(up2)
                if not m:
                    continue
                dt = parse_date_match(m)
                if not dt:
                    continue
                iso = dt.strftime('%Y-%m-%d')
                counts[iso] = counts.get(iso, 0) + 1
                first_idx.setdefault(iso, i)
        return counts, first_idx
